def run_inline_com_preflight():
    v = globals().get("Visum")
    if v is None:
        v = globals().get("COM")
    root, source = project_output_root(v)
    folder = root / ("RUN_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
    folder.mkdir(parents=True, exist_ok=False)
    try:
        report = collect_live_api(v, DIAGNOSTIC_CONFIG, folder)
        report["output_root_source"] = source
        (folder / "COM_API_PREFLIGHT.json").write_text(json.dumps(json_value(report), indent=2, ensure_ascii=False), encoding="utf-8")
    except Exception:
        (folder / "99_PROBE_TRACEBACK.txt").write_text(traceback.format_exc(), encoding="utf-8")
        (folder / "00_FINAL_STATUS.txt").write_text("PROBE_ERROR_NO_MODEL_WRITES\n", encoding="utf-8")
    (root / "LATEST_RUN.txt").write_text(str(folder)+"\n", encoding="utf-8")
    return str(folder)

# Inline source has no stable __name__/__file__; do not rely on either.
if globals().get("Visum") is not None or globals().get("COM") is not None or globals().get("__name__") == "__main__":
    R1_COM_PREFLIGHT_OUTPUT = run_inline_com_preflight()
